import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import Slider, { sliderClasses, type SliderProps } from '@mui/material/Slider';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSlotProps } from '@mui/material/utils';
import type { SystemStyleObject } from '@mui/system';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type ElementType } from 'react';
import { svTokens } from '../../theme/tokens';

export type SvSliderProps<
  RootComponent extends ElementType = 'span',
  AdditionalProps = Record<never, never>,
  Value extends number | readonly number[] = number | number[],
> = SliderProps<RootComponent, AdditionalProps, Value>;

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvSlider: SvSliderProps;
  }
  interface Components {
    SvSlider?:
      { defaultProps?: Partial<SvSliderProps> | undefined } | undefined;
  }
}

type Slots = NonNullable<SvSliderProps['slotProps']>;
function thumbSx(theme: Theme): SystemStyleObject<Theme> {
  return {
    width: 'var(--SvSlider-thumb-size)',
    height: 'var(--SvSlider-thumb-size)',
    '&::before': { boxShadow: 'none' },
    '&:hover': {
      boxShadow: '0 0 0 7px color-mix(in srgb, currentColor 24%, transparent)',
      '@media (hover: none)': { boxShadow: 'none' },
    },
    [`&.${sliderClasses.focusVisible}`]: {
      boxShadow: 'none',
      outline: `2px solid ${svTokens(theme).focus}`,
      outlineOffset: 3,
      '@media (forced-colors: active)': { outlineColor: 'Highlight' },
    },
    [`&.${sliderClasses.active}`]: {
      boxShadow: '0 0 0 14px color-mix(in srgb, currentColor 16%, transparent)',
    },
    [`&.${sliderClasses.disabled}`]: { boxShadow: 'none' },
  };
}
const railSx: SxProps<Theme> = {
  backgroundColor: 'var(--SvSlider-rail)',
  opacity: 1,
  [`.${sliderClasses.disabled} &`]: {
    backgroundColor: 'currentColor',
    opacity: 0.38,
  },
};
const trackSx: SxProps<Theme> = {
  backgroundColor: 'var(--SvSlider-track)',
  boxSizing: 'border-box',
  '@media (forced-colors: none)': { border: 'none' },
};

export const SvSlider = forwardRef<HTMLSpanElement, SvSliderProps>(
  function SvSlider(inProps, ref) {
    const muiDefaults = useDefaultProps<SvSliderProps>({
      props: {},
      name: 'MuiSlider',
    });
    const svDefaults = useDefaultProps<SvSliderProps>({
      props: {},
      name: 'SvSlider',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvSlider' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiSlider' });
    const {
      className,
      sx: _sx,
      slotProps: _slotProps,
      orientation = 'horizontal',
      size = 'medium',
      color = 'primary',
      track = 'normal',
      ...props
    } = resolved;
    const sliderSx: SxProps<Theme> = (theme) => ({
      '--SvSlider-accent': svTokens(theme).accent,
      '--SvSlider-stroke': `var(--SvSlider-default-stroke, ${svTokens(theme).stroke})`,
      '--SvSlider-thumb-size': size === 'small' ? '12px' : '18px',
      '--SvSlider-rail':
        track === 'inverted' ? 'currentColor' : 'var(--SvSlider-stroke)',
      '--SvSlider-track':
        track === 'inverted' ? 'var(--SvSlider-stroke)' : 'currentColor',
      ...(color === 'primary' && { color: 'var(--SvSlider-accent)' }),
      minWidth: 0,
      borderRadius: 0,
      ...(orientation === 'vertical'
        ? { width: size === 'small' ? '2px' : '3px', height: '100%' }
        : { height: size === 'small' ? '2px' : '3px' }),
      [`&.${sliderClasses.disabled}`]: { '--SvSlider-track': 'currentColor' },
      '@media (prefers-reduced-motion: reduce)': {
        [`&, & .${sliderClasses.thumb}, & .${sliderClasses.track}, & .${sliderClasses.valueLabel}, & *::before, & *::after`]:
          { transition: 'none' },
      },
    });
    // Resolve slot layers separately: MUI default-prop resolution replaces sx fields.
    const slot = <K extends keyof Slots>(name: K): NonNullable<Slots[K]> => {
      return mergeSlotProps(
        inProps.slotProps?.[name],
        mergeSlotProps(
          svDefaults.slotProps?.[name],
          muiDefaults.slotProps?.[name] ?? {}
        )
      ) as NonNullable<Slots[K]>;
    };
    const rootSx = mergeSx(sliderSx, muiDefaults.sx, svDefaults.sx, inProps.sx);
    return (
      <Slider
        {...props}
        ref={ref}
        orientation={orientation}
        size={size}
        color={color}
        track={track}
        className={clsx('SvSlider-root', className)}
        sx={rootSx}
        slotProps={{
          root: mergeSlotProps(slot('root'), { sx: rootSx }),
          thumb: mergeSlotProps(slot('thumb'), { sx: thumbSx }),
          rail: mergeSlotProps(slot('rail'), { sx: railSx }),
          track: mergeSlotProps(slot('track'), { sx: trackSx }),
          input: slot('input'),
          mark: slot('mark'),
          markLabel: slot('markLabel'),
          valueLabel: slot('valueLabel'),
        }}
      />
    );
  }
  // Values and root props pass through unchanged, including readonly arrays.
  // Restore MUI's value-specific and polymorphic overloads erased by forwardRef.
) as typeof Slider;
